  var D=window.ARCHIVE_DATA;
  D.categories=[{"id":"anomalies","code":"ANOM","name":"异常档案","nameEn":"Anomaly Archive","desc":"收录被记录在案的异常实体、现象、地点与物品。每条档案附有应对协议与危险分级。","icon":"⬡","source":"都市传说/ + 行动代号/","subcats":[]},{"id":"organizations","code":"ORG","name":"组织名录","nameEn":"Organization Registry","desc":"红月之下活跃的各类组织、企业、教会与机构的核心档案。","icon":"◈","source":"红月之下/核心档案/","subcats":[]},{"id":"deities","code":"DEI","name":"神祇图鉴","nameEn":"Deity Codex","desc":"旧神时代的众神名录，附神像图与权柄领域。","icon":"✦","source":"世界观目前/神/","subcats":[]},{"id":"eras","code":"ERA","name":"纪元卷宗","nameEn":"Era Codex","desc":"世界观三大纪元（神代、黑蚀、寂祀）与《喀尔迦书》《灾变纪》等典籍文本。","icon":"☉","source":"世界观目前/第一纪元/ + 第二纪元/ + 喀尔迦书/","subcats":[]},{"id":"timelines","code":"TL","name":"组织时间线","nameEn":"Organization Timelines","desc":"各组织历史事件的纵向时间线，可交叉对照。","icon":"◷","source":"红月之下/组织时间线/","subcats":[]}];
